INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_07','V1014','阮明',7,'太好了，那我现在立刻发送截图，麻烦您尽快核对处理。','tài hǎo le， nà wǒ xiàn zài lì kè fā sòng jié tú， má fán nín jǐn kuài hé duì chǔ lǐ。','Tuyệt quá, vậy tôi gửi ảnh chụp ngay bây giờ, phiền chị kiểm tra xử lý giúp càng sớm càng tốt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_08','V1014','陈会计',8,'我今天下班前完成对账，要是资金仍未同步，你明天再来一趟。','wǒ jīn tiān xià bān qián wán chéng duì zhàng， yào shì zī jīn réng wèi tóng bù， nǐ míng tiān zài lái yī tàng。','Hôm nay trước giờ tan làm tôi sẽ hoàn tất đối soát, nếu tiền vẫn chưa đồng bộ thì mai anh ghé lại một lần nữa nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1015','SKC1','论文截止日前电脑硬盘崩溃文件丢失，找授课老师申请延期并借用图书馆设备',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1015','SIT1015','P1','twist','ban_chinh_thuc',NULL,'国内高校论文延期需提交书面说明+客观事故证明，任课老师无权私自延期，必须上报教务审批。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_01','V1015','阮明',1,'周老师，不好意思打扰您，我电脑硬盘突然损坏，整篇毕业论文全部丢失了啊。','zhōu lǎo shī， bù hǎo yì sī dǎ rǎo nín， wǒ diàn nǎo yìng pán tū rán sǔn huài， zhěng piān bì yè lùn wén quán bù diū shī le a。','Thầy Chu, xin lỗi làm phiền thầy, ổ cứng máy tính em bỗng dưng hỏng, toàn bộ luận văn tốt nghiệp mất sạch rồi ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_02','V1015','周教授',2,'怎么会这么不巧？距离提交截止日期只剩明天中午了呢。','zěn me huì zhè me bù qiǎo？ jù lí tí jiāo jié zhǐ rì qī zhǐ shèng míng tiān zhōng wǔ le ne。','Sao lại xui xẻo đúng lúc này chứ? Chỉ còn đến trưa mai là hạn nộp bài rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_03','V1015','阮明',3,'我没有备份文件，硬盘完全读不出来，维修店说很难恢复数据。','wǒ méi yǒu bèi fèn wén jiàn， yìng pán wán quán dú bù chū lái， wéi xiū diàn shuō hěn nán huī fù shù jù。','Em không có bản sao lưu, ổ cứng hoàn toàn không đọc được nữa, tiệm sửa máy nói rất khó khôi phục dữ liệu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_04','V1015','周教授',4,'我理解你的突发状况，但学院统一截止时间不能随便延后，流程很严格。','wǒ lǐ jiě nǐ de tū fā zhuàng kuàng， dàn xué yuàn tǒng yī jié zhǐ shí jiān bù néng suí biàn yán hòu， liú chéng hěn yán gé。','Thầy hiểu tình huống bất ngờ của em, nhưng thời hạn chung của khoa không thể tùy tiện lùi lại được, quy trình rất nghiêm ngặt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_05','V1015','阮明',5,'我能不能申请三天延期？图书馆有备用电脑，我可以连夜重新写完初稿。','wǒ néng bù néng shēn qǐng sān tiān yán qī？ tú shū guǎn yǒu bèi yòng diàn nǎo， wǒ kě yǐ lián yè chóng xīn xiě wán chū gǎo。','Em xin gia hạn ba ngày được không ạ? Thư viện có máy tính dự phòng, em có thể thức đêm viết lại bản nháp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_06','V1015','周教授',6,'你先写一份书面情况说明，附上电脑维修单据，我帮你向学院教务报备。','nǐ xiān xiě yī fèn shū miàn qíng kuàng shuō míng， fù shàng diàn nǎo wéi xiū dān jù， wǒ bāng nǐ xiàng xué yuàn jiào wù bào bèi。','Em viết trước một bản tường trình bằng văn bản, kèm theo biên nhận sửa máy, thầy sẽ giúp em báo cáo lên phòng đào tạo của khoa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_07','V1015','阮明',7,'太感谢老师了，我现在就去图书馆借设备，通宵赶写论文。','tài gǎn xiè lǎo shī le， wǒ xiàn zài jiù qù tú shū guǎn jiè shè bèi， tōng xiāo gǎn xiě lùn wén。','Em cảm ơn thầy nhiều lắm ạ, em ra thư viện mượn máy ngay bây giờ, thức trắng đêm viết cho xong luận văn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_08','V1015','周教授',8,'尽力加快进度，教务那边最多只能批准三天缓冲期，别再拖延啦。','jìn lì jiā kuài jìn dù， jiào wù nà biān zuì duō zhǐ néng pī zhǔn sān tiān huǎn chōng qī， bié zài tuō yán la。','Cố gắng đẩy nhanh tiến độ nhé, bên phòng đào tạo cùng lắm chỉ có thể duyệt cho ba ngày gia hạn thôi, đừng để trễ nữa đấy.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1016','SKC1','出入境预约号当日失效，携带齐全材料现场窗口申请加急受理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1016','SIT1016','P1','that_bai_nhe','ban_chinh_thuc',NULL,'出入境线上预约实行分时段限号制度，普通出行、学术活动不纳入紧急加急受理范围，仅重大医疗、亲属变故可走绿色通道。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_01','V1016','阮明',1,'你好，我线上预约的今天办理签证续签，预约号显示失效了，材料全都带齐了。','nǐ hǎo， wǒ xiàn shàng yù yuē de jīn tiān bàn lǐ qiān zhèng xù qiān， yù yuē hào xiǎn shì shī xiào le， cái liào quán dōu dài qí le。','Chào chị, tôi đặt lịch trực tuyến hôm nay để làm thủ tục gia hạn visa, nhưng số thứ tự lại báo hết hiệu lực, giấy tờ tôi mang đầy đủ rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_02','V1016','小徐',2,'预约号过期只能重新线上预约，线下窗口不接受无号业务办理哦。','yù yuē hào guò qī zhǐ néng chóng xīn xiàn shàng yù yuē， xiàn xià chuāng kǒu bù jiē shòu wú hào yè wù bàn lǐ ó。','Số đặt lịch hết hạn thì chỉ có thể đặt lại trực tuyến thôi, quầy trực tiếp không tiếp nhận hồ sơ không có số đâu ạ.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_03','V1016','阮明',3,'我下周就要离校出差，根本没时间重新预约，能不能通融一下加急处理呢？','wǒ xià zhōu jiù yào lí xiào chū chāi， gēn běn méi shí jiān chóng xīn yù yuē， néng bù néng tōng róng yī xià jiā jí chǔ lǐ ne？','Tuần sau tôi phải rời trường đi công tác rồi, thực sự không có thời gian đặt lại lịch, chị có thể linh động xử lý gấp giúp tôi không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_04','V1016','小徐',4,'加急业务仅限紧急就医、亲属病危这类特殊情况，出行出差不符合加急标准。','jiā jí yè wù jǐn xiàn jǐn jí jiù yī、 qīn shǔ bìng wēi zhè lèi tè shū qíng kuàng， chū xíng chū chāi bù fú hé jiā jí biāo zhǔn。','Xử lý khẩn cấp chỉ áp dụng cho các trường hợp đặc biệt như cấp cứu y tế, người thân nguy kịch, đi công tác không thuộc diện được xử lý gấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_05','V1016','阮明',5,'我是留学生，外出参加国际学术会议，会议邀请函我随身带来了啊。','wǒ shì liú xué shēng， wài chū cān jiā guó jì xué shù huì yì， huì yì yāo qǐng hán wǒ suí shēn dài lái le a。','Tôi là du học sinh, đi dự hội nghị học thuật quốc tế, thư mời hội nghị tôi mang theo đây ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_06','V1016','小徐',6,'我帮你咨询窗口主管，你先在这里等候几分钟，不要离开。','wǒ bāng nǐ zī xún chuāng kǒu zhǔ guǎn， nǐ xiān zài zhè lǐ děng hòu jǐ fēn zhōng， bú yào lí kāi。','Để tôi hỏi giúp anh bên quản lý quầy, anh cứ chờ ở đây vài phút, đừng đi đâu nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_07','V1016','阮明',7,'麻烦你多帮忙说说，错过会议对我的学业影响很大。','má fán nǐ duō bāng máng shuō shuō， cuò guò huì yì duì wǒ de xué yè yǐng xiǎng hěn dà。','Phiền chị giúp tôi nói thêm với, lỡ mất hội nghị thì ảnh hưởng lớn đến việc học của tôi lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_08','V1016','小徐',8,'主管回复了，依旧无法现场受理，只能明天重新抢预约号。','zhǔ guǎn huí fù le， yī jiù wú fǎ xiàn chǎng shòu lǐ， zhǐ néng míng tiān chóng xīn qiǎng yù yuē hào。','Quản lý đã trả lời rồi, vẫn không thể tiếp nhận trực tiếp được, chỉ có thể mai quay lại giành số đặt lịch lại thôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1017','SKC1','诈骗来电谎称家人重病要求汇款，冷静核实后联系学院反诈老师',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1017','SIT1017','P1','suon_se','ban_chinh_thuc',NULL,'国内高校会定期开展留学生反诈宣讲，遭遇疑似诈骗可直接联系国际学院辅导员，同步上报公安反诈平台。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_01','V1017','阮明',1,'郑老师，我刚刚接到一通陌生电话，说我母亲重病住院，急需我立刻转账过去。','zhèng lǎo shī， wǒ gāng gāng jiē dào yí tòng mò shēng diàn huà， shuō wǒ mǔ qīn zhòng bìng zhù yuàn， jí xū wǒ lì kè zhuǎn zhàng guò qù。','Thầy Trịnh ơi, em vừa nhận được một cuộc gọi lạ, nói là mẹ em bị bệnh nặng phải nhập viện, cần em chuyển tiền ngay lập tức.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_02','V1017','郑老师',2,'你先别慌，有没有第一时间通过视频电话联系家里确认情况？','nǐ xiān bié huāng， yǒu méi yǒu dì yī shí jiān tōng guò shì pín diàn huà lián xì jiā lǐ què rèn qíng kuàng？','Em đừng hoảng, em đã gọi video ngay để xác nhận tình hình với gia đình chưa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_03','V1017','阮明',3,'我马上打视频给我妈妈，她身体好好的，根本没有生病这回事呢。','wǒ mǎ shàng dǎ shì pín gěi wǒ mā mā， tā shēn tǐ hǎo hǎo de， gēn běn méi yǒu shēng bìng zhè huí shì ne。','Em gọi video cho mẹ ngay, mẹ em vẫn khỏe re, làm gì có chuyện bệnh tật gì đâu.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_04','V1017','郑老师',4,'这是典型跨境冒充亲属诈骗，很多留学生都接到过同类来电。','zhè shì diǎn xíng kuà jìng mào chōng qīn shǔ zhà piàn， hěn duō liú xué shēng dōu jiē dào guò tóng lèi lái diàn。','Đây là kiểu lừa đảo giả mạo người thân xuyên biên giới điển hình, nhiều du học sinh cũng từng nhận được cuộc gọi tương tự.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_05','V1017','阮明',5,'骗子还准确说出我的姓名和家乡信息，差点我就准备转账了，太吓人啦。','piàn zi hái zhǔn què shuō chū wǒ de xìng míng hé jiā xiāng xìn xī， chà diǎn wǒ jiù zhǔn bèi zhuǎn zhàng le， tài xià rén la。','Bọn lừa đảo còn nói đúng tên và thông tin quê quán của em, suýt nữa em đã chuyển tiền rồi, đáng sợ thật đó.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_06','V1017','郑老师',6,'把对方的来电号码发给我，学院统一上报反诈中心备案拦截。','bǎ duì fāng de lái diàn hào mǎ fā gěi wǒ， xué yuàn tǒng yī shàng bào fǎn zhà zhōng xīn bèi àn lán jié。','Em gửi số điện thoại của đối tượng đó cho thầy, nhà trường sẽ báo cáo lên trung tâm chống lừa đảo để ghi nhận và chặn số.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_07','V1017','阮明',7,'好，我现在转发号码，之后再有陌生要钱电话我都会先来问您。','hǎo， wǒ xiàn zài zhuǎn fā hào mǎ， zhī hòu zài yǒu mò shēng yào qián diàn huà wǒ dōu huì xiān lái wèn nín。','Dạ, em gửi số ngay đây, sau này có cuộc gọi lạ đòi tiền em sẽ hỏi thầy trước ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_08','V1017','郑老师',8,'记住，凡是催你立刻转账的陌生来电，一律不要相信，先核实家人。','jì zhù， fán shì cuī nǐ lì kè zhuǎn zhàng de mò shēng lái diàn， yī lǜ bú yào xiāng xìn， xiān hé shí jiā rén。','Nhớ nhé, hễ cuộc gọi lạ nào giục em chuyển tiền ngay thì đừng tin, phải xác minh với gia đình trước đã.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1018','SKC1','校园学习账号被盗用登录，联系学校信息中心紧急冻结账号',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1018','SIT1018','P1','twist','ban_chinh_thuc',NULL,'国内高校校园账号绑定学籍、选课、图书馆借阅权限，被盗用可能泄露个人学籍信息，必须线下核验身份永久冻结。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_01','V1018','阮明',1,'您好，我的校园学习平台账号异地登录，应该是被盗用了，麻烦帮忙冻结账号吧。','nín hǎo， wǒ de xiào yuán xué xí píng tái zhàng hào yì dì dēng lù， yīng gāi shì bèi dào yòng le， má fán bāng máng dòng jié zhàng hào ba。','Chào anh, tài khoản nền tảng học tập của em bị đăng nhập từ nơi khác, chắc là bị đánh cắp rồi, phiền anh giúp em khóa tài khoản lại.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_02','V1018','小高',2,'请提供你的学号、实名姓名，我先查询账号登录记录看看。','qǐng tí gōng nǐ de xué hào、 shí míng xìng míng， wǒ xiān chá xún zhàng hào dēng lù jì lù kàn kàn。','Em cho anh xin mã số sinh viên và họ tên thật, để anh kiểm tra lịch sử đăng nhập tài khoản trước đã.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_03','V1018','阮明',3,'学号20230418，姓名阮明，系统提示今早凌晨在外地设备登录啊。','xué hào 20230418， xìng míng ruǎn míng， xì tǒng tí shì jīn zǎo líng chén zài wài dì shè bèi dēng lù a。','Mã số sinh viên 20230418, tên Nguyễn Minh, hệ thống báo là sáng sớm nay có thiết bị ở nơi khác đăng nhập đó.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_04','V1018','小高',4,'账号冻结需要核验身份，你要携带学生证线下到机房办理完整锁定手续。','zhàng hào dòng jié xū yào hé yàn shēn fèn， nǐ yào xié dài xué shēng zhèng xiàn xià dào jī fáng bàn lǐ wán zhěng suǒ dìng shǒu xù。','Việc khóa tài khoản cần xác minh danh tính, em phải mang thẻ sinh viên đến phòng máy trực tiếp để làm thủ tục khóa hoàn toàn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_05','V1018','阮明',5,'我现在在教学楼上课走不开，能不能线上临时冻结，等下课再去机房？','wǒ xiàn zài zài jiào xué lóu shàng kè zǒu bù kāi， néng bù néng xiàn shàng lín shí dòng jié， děng xià kè zài qù jī fáng？','Em đang học trên giảng đường không đi được, anh có thể tạm khóa online trước không, chờ tan học em qua phòng máy sau?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_06','V1018','小高',6,'我可以先临时限制登录两小时，超时会自动解除，线下才能永久锁定。','wǒ kě yǐ xiān lín shí xiàn zhì dēng lù liǎng xiǎo shí， chāo shí huì zì dòng jiě chú， xiàn xià cái néng yǒng jiǔ suǒ dìng。','Anh có thể tạm giới hạn đăng nhập trong hai tiếng, quá giờ sẽ tự động mở lại, phải làm trực tiếp mới khóa vĩnh viễn được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_07','V1018','阮明',7,'两小时足够我下课过去，麻烦您现在先帮我临时锁上账号。','liǎng xiǎo shí zú gòu wǒ xià kè guò qù， má fán nín xiàn zài xiān bāng wǒ lín shí suǒ shàng zhàng hào。','Hai tiếng là đủ để em tan học qua rồi, phiền anh khóa tạm tài khoản giúp em trước nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_08','V1018','小高',8,'已经临时限制登录了，尽快带证件过来重置密码完善安全验证。','yǐ jīng lín shí xiàn zhì dēng lù le， jǐn kuài dài zhèng jiàn guò lái zhòng zhì mì mǎ wán shàn ān quán yàn zhèng。','Đã tạm khóa đăng nhập rồi đó, em mang giấy tờ qua sớm để đặt lại mật khẩu và hoàn thiện xác thực bảo mật.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1019','SKC1','社交平台私人照片被恶意转发骚扰，到学校保卫处寻求介入处理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1019','SIT1019','P1','suon_se','chinh_thuc',NULL,'个人肖像被恶意转发骚扰属于侵权行为，学校保卫处可出具证明协助学生向社交平台申请删除内容、封禁侵权账号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_01','V1019','阮明',1,'李干事您好，有人保存我的私人生活照片，转发到社交平台私信骚扰我。','lǐ gàn shì nín hǎo， yǒu rén bǎo cún wǒ de sī rén shēng huó zhào piàn， zhuǎn fā dào shè jiāo píng tái sī xìn sāo rǎo wǒ。','Chào cán bộ Lý, có người lưu lại ảnh sinh hoạt riêng tư của tôi rồi chuyển tiếp qua tin nhắn riêng trên mạng xã hội để quấy rối tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_02','V1019','李干事',2,'你先把对方骚扰截图、转发照片的完整记录全部截图保存好。','nǐ xiān bǎ duì fāng sāo rǎo jié tú、 zhuǎn fā zhào piān de wán zhěng jì lù quán bù jié tú bǎo cún hǎo。','Em chụp màn hình lưu lại đầy đủ toàn bộ tin nhắn quấy rối và ảnh bị chuyển tiếp của đối tượng đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_03','V1019','阮明',3,'所有聊天记录我都存好了，对方是校外人员，我不知道对方真实身份呢。','suǒ yǒu liáo tiān jì lù wǒ dōu cún hǎo le， duì fāng shì xiào wài rén yuán， wǒ bù zhī dào duì fāng zhēn shí shēn fèn ne。','Toàn bộ tin nhắn tôi đã lưu lại hết rồi, đối tượng đó là người ngoài trường, tôi không biết danh tính thật của họ là ai.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_04','V1019','李干事',4,'我们会出具学校证明，协助你联系平台客服调取对方注册信息。','wǒ men huì chū jù xué xiào zhèng míng， xié zhù nǐ lián xì píng tái kè fú diào qǔ duì fāng zhù cè xìn xī。','Nhà trường sẽ cấp giấy xác nhận, hỗ trợ em liên hệ với bộ phận chăm sóc khách hàng của nền tảng để tra thông tin đăng ký của đối tượng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_05','V1019','阮明',5,'对方持续发消息骚扰，严重影响我上课和休息，希望尽快制止。','duì fāng chí xù fā xiāo xī sāo rǎo， yán zhòng yǐng xiǎng wǒ shàng kè hé xiū xī， xī wàng jǐn kuài zhì zhǐ。','Đối tượng liên tục nhắn tin quấy rối, ảnh hưởng nghiêm trọng đến việc học và nghỉ ngơi của tôi, mong sớm can thiệp chấm dứt việc này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_06','V1019','李干事',6,'我先登记你的情况，今天就发函给平台要求下架相关照片。','wǒ xiān dēng jì nǐ de qíng kuàng， jīn tiān jiù fā hán gěi píng tái yāo qiú xià jià xiāng guān zhào piān。','Tôi sẽ ghi nhận trường hợp của em trước, hôm nay sẽ gửi công văn cho nền tảng yêu cầu gỡ bỏ những ảnh liên quan.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_07','V1019','阮明',7,'太感谢您了，我之前不知道学校保卫处可以处理网络骚扰问题。','tài gǎn xiè nín le， wǒ zhī qián bù zhī dào xué xiào bǎo wèi chù kě yǐ chǔ lǐ wǎng luò sāo rǎo wèn tí。','Tôi cảm ơn cán bộ rất nhiều, trước đây tôi không biết phòng bảo vệ nhà trường có thể xử lý cả vấn đề quấy rối trên mạng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_08','V1019','李干事',8,'校内师生遭遇网络侵权、骚扰都可以来报备，我们会配合平台维权。','xiào nèi shī shēng zāo yù wǎng luò qīn quán、 sāo rǎo dōu kě yǐ lái bào bèi， wǒ men huì pèi hé píng tái wéi quán。','Thầy cô và sinh viên trong trường nếu gặp phải xâm phạm quyền lợi hay quấy rối trên mạng đều có thể đến trình báo, chúng tôi sẽ phối hợp với nền tảng để bảo vệ quyền lợi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1020','SKC1','社团活动现场两名同学激烈争吵，上前劝解并通知社团负责人',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1020','SIT1020','P1','twist','tuy_y',NULL,'国内校园社团公共场合发生争吵会影响社团评优，负责人一般会分开双方私下调解，避免当众激化矛盾。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_01','V1020','阮明',1,'小宇，你快过来一下，策划部两位同学吵得特别凶，谁都不肯让步啊。','xiǎo yǔ， nǐ kuài guò lái yī xià， cè huà bù liǎng wèi tóng xué chǎo dé tè bié xiōng， shéi dōu bù kěn ràng bù a。','Tiểu Vũ ơi, cậu qua đây nhanh lên, hai bạn bên ban tổ chức đang cãi nhau dữ lắm, không ai chịu nhường ai cả.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_02','V1020','小宇',2,'怎么回事？活动现场还有这么多新生，吵起来影响太不好了吧。','zěn me huí shì？ huó dòng xiàn chǎng hái yǒu zhè me duō xīn shēng， chǎo qǐ lái yǐng xiǎng tài bù hǎo le ba。','Chuyện gì vậy? Ở hiện trường sự kiện còn bao nhiêu tân sinh viên, cãi nhau vậy ảnh hưởng không hay chút nào đâu.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_03','V1020','阮明',3,'两人对活动预算分配意见不合，声音越来越大，周围同学都在围观。','liǎng rén duì huó dòng yù suàn fēn pèi yì jiàn bù hé， shēng yīn yuè lái yuè dà， zhōu wéi tóng xué dōu zài wéi guān。','Hai người bất đồng về việc phân bổ ngân sách hoạt động, càng nói càng to tiếng, xung quanh mọi người đứng xem đông lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_04','V1020','小宇',4,'你先把两人分开，分别带到两边休息室，别在大厅当众争执。','nǐ xiān bǎ liǎng rén fēn kāi， fēn bié dài dào liǎng biān xiū xī shì， bié zài dà tīng dāng zhòng zhēng zhí。','Cậu tách hai người ra trước đi, dẫn mỗi người vào một phòng nghỉ riêng, đừng để họ cãi nhau ngay giữa sảnh thế này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_05','V1020','阮明',5,'我劝了半天，两人情绪都很激动，根本不愿意冷静沟通呢。','wǒ quàn le bàn tiān， liǎng rén qíng xù dōu hěn jī dòng， gēn běn bù yuàn yì lěng jìng gōu tōng ne。','Mình khuyên mãi mà cả hai đều đang kích động lắm, chẳng chịu bình tĩnh nói chuyện gì cả.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_06','V1020','小宇',6,'我现在过去单独跟他们谈话，你帮忙安抚一下围观的新生。','wǒ xiàn zài guò qù dān dú gēn tā men tán huà， nǐ bāng máng ān fǔ yī xià wéi guān de xīn shēng。','Giờ mình qua nói chuyện riêng với từng người, cậu giúp trấn an mấy bạn tân sinh viên đang đứng xem nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_07','V1020','阮明',7,'没问题，我先转移大家注意力，避免场面变得更尴尬。','méi wèn tí， wǒ xiān zhuǎn yí dà jiā zhù yì lì， bì miǎn chǎng miàn biàn dé gèng gān gà。','Được, để mình hướng sự chú ý của mọi người đi chỗ khác, tránh tình hình thêm lúng túng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_08','V1020','小宇',8,'辛苦你了，社团有矛盾及时告诉我，别任由冲突发酵。','xīn kǔ nǐ le， shè tuán yǒu máo dùn jí shí gào sù wǒ， bié rèn yóu chōng tū fā jiào。','Cậu vất vả rồi, sau này câu lạc bộ có mâu thuẫn gì thì báo mình ngay, đừng để xung đột âm ỉ lâu.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1021','SKC1','自习室同学突发癫痫，疏散人群、联系校医、维持现场秩序',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1021','SIT1021','P1','suon_se','ban_chinh_thuc',NULL,'国内校园普及癫痫急救基础常识，发病时禁止强行束缚患者肢体，保持通风、清理周边硬物是基础急救方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_01','V1021','阮明',1,'思琪学姐，这边有位同学突然倒地抽搐，像是癫痫发作了！','sī qí xué jiě， zhè biān yǒu wèi tóng xué tū rán dǎo dì chōu chù， xiàng shì diān xián fā zuò le！','Chị Tư Kỳ ơi, ở đây có một bạn đột nhiên ngã xuống co giật, có vẻ như đang lên cơn động kinh!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_02','V1021','思琪',2,'大家先不要围过来，全部后退留出通风空间，别挤在这里啊。','dà jiā xiān bú yào wéi guò lái， quán bù hòu tuì liú chū tōng fēng kōng jiān， bié jǐ zài zhè lǐ a。','Mọi người đừng xúm lại, lùi ra hết để có chỗ thoáng khí, đừng chen chúc ở đây.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_03','V1021','阮明',3,'我已经把周围桌椅挪开，避免他磕碰受伤，现在要立刻联系校医吧？','wǒ yǐ jīng bǎ zhōu wéi zhuō yǐ nuó kāi， bì miǎn tā kē pèng shòu shāng， xiàn zài yào lì kè lián xì xiào yī ba？','Em đã dời bàn ghế xung quanh ra rồi để tránh bạn ấy va đập bị thương, giờ mình gọi ngay cho phòng y tế trường nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_04','V1021','思琪',4,'我马上拨打校医应急电话，你帮忙拿一件外套垫在他头下面。','wǒ mǎ shàng bō dǎ xiào yī yìng jí diàn huà， nǐ bāng máng ná yī jiàn wài tào diàn zài tā tóu xià miàn。','Chị gọi ngay số khẩn cấp của phòng y tế, em lấy giúp chị một cái áo khoác lót dưới đầu bạn ấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_05','V1021','阮明',5,'好，我按住他身边的桌椅，防止抽搐时撞到边角，现在意识不清醒呢。','hǎo， wǒ àn zhù tā shēn biān de zhuō yǐ， fáng zhǐ chōu chù shí zhuàng dào biān jiǎo， xiàn zài yì shí bù qīng xǐng ne。','Vâng, em giữ mấy cái bàn ghế bên cạnh bạn ấy để tránh lúc co giật va vào góc cạnh, giờ bạn ấy đang mất ý thức rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_06','V1021','思琪',6,'不要强行按压他的四肢，等校医过来再做专业处理，大家安静一点。','bú yào qiáng xíng àn yā tā de sì zhī， děng xiào yī guò lái zài zuò zhuān yè chǔ lǐ， dà jiā ān jìng yì diǎn。','Đừng cố giữ chặt tay chân bạn ấy, để bác sĩ trường đến xử lý chuyên môn, mọi người trật tự giúp chị một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_07','V1021','阮明',7,'我会维持秩序，不让围观同学上前触碰，等待医护人员到场。','wǒ huì wéi chí zhì xù， bù ràng wéi guān tóng xué shàng qián chù pèng， děng dài yī hù rén yuán dào chǎng。','Em sẽ giữ trật tự, không để các bạn đứng xem lại gần chạm vào, chờ nhân viên y tế đến.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_08','V1021','思琪',8,'多亏你及时发现，慌乱围观很容易给发病同学造成二次伤害。','duō kuī nǐ jí shí fā xiàn， huāng luàn wéi guān hěn róng yì gěi fā bìng tóng xué zào chéng èr cì shāng hài。','May mà em phát hiện kịp thời, chứ mọi người hoảng loạn xúm vào xem rất dễ khiến bạn ấy bị tổn thương thêm lần nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1022','SKC1','校外租房房东私自换锁不让进门，拨打社区民警协调房屋纠纷',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1022','SIT1022','P1','that_bai_nhe','chinh_thuc',NULL,'租房纠纷属于民事纠纷，民警仅负责现场调解，无权强制破门，双方无法达成一致需走法院民事诉讼。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_01','V1022','阮明',1,'王警官您好，我租的房子房东私自更换门锁，不让我进屋拿个人物品。','wáng jǐng guān nín hǎo， wǒ zū de fáng zi fáng dōng sī zì gēng huàn mén suǒ， bù ràng wǒ jìn wū ná gè rén wù pǐn。','Chào đồng chí công an Vương, chủ nhà tôi thuê tự ý thay khóa cửa, không cho tôi vào lấy đồ đạc cá nhân.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_02','V1022','王民警',2,'出示你的租房合同、身份证件，跟我说清楚房东换锁的原因吧。','chū shì nǐ de zū fáng hé tóng、 shēn fèn zhèng jiàn， gēn wǒ shuō qīng chǔ fáng dōng huàn suǒ de yuán yīn ba。','Anh/chị đưa hợp đồng thuê nhà và giấy tờ tùy thân, rồi nói rõ cho tôi lý do chủ nhà đổi khóa.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_03','V1022','阮明',3,'房租我按时足额缴纳，房东单方面想涨租，我没同意就直接换锁了啊。','fáng zū wǒ àn shí zú é jiǎo nà， fáng dōng dān fāng miàn xiǎng zhǎng zū， wǒ méi tóng yì jiù zhí jiē huàn suǒ le a。','Tiền thuê nhà tôi đóng đúng hạn đầy đủ, chủ nhà đơn phương muốn tăng giá thuê, tôi không đồng ý thì họ liền đổi khóa luôn.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_04','V1022','王民警',4,'私自换锁扣押租客私人物品属于违规，我现在联系房东到场调解。','sī zì huàn suǒ kòu yā zū kè sī rén wù pǐn shǔ yú wéi guī， wǒ xiàn zài lián xì fáng dōng dào chǎng tiáo jiě。','Việc tự ý đổi khóa và giữ đồ đạc cá nhân của người thuê là vi phạm, tôi sẽ liên hệ chủ nhà đến để hòa giải ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_05','V1022','阮明',5,'我的电脑、居留卡全都放在屋内，今晚没地方住，能不能先进屋拿东西？','wǒ de diàn nǎo、 jū liú kǎ quán dōu fàng zài wū nèi， jīn wǎn méi dì fāng zhù， néng bù néng xiān jìn wū ná dōng xī？','Máy tính, thẻ cư trú của tôi đều để trong nhà cả, tối nay tôi không có chỗ ở, có thể cho tôi vào lấy đồ trước được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_06','V1022','王民警',6,'调解需要双方到场，房东半小时后才能过来，暂时无法开门。','tiáo jiě xū yào shuāng fāng dào chǎng， fáng dōng bàn xiǎo shí hòu cái néng guò lái， zàn shí wú fǎ kāi mén。','Việc hòa giải cần cả hai bên có mặt, chủ nhà nửa tiếng nữa mới tới được, nên tạm thời chưa thể mở cửa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_07','V1022','阮明',7,'那我今晚只能临时住酒店，贵重证件都在房间里，实在不放心。','nà wǒ jīn wǎn zhǐ néng lín shí zhù jiǔ diàn， guì zhòng zhèng jiàn dōu zài fáng jiān lǐ， shí zài bù fàng xīn。','Vậy tối nay tôi đành tạm ở khách sạn, nhưng giấy tờ quan trọng đều ở trong phòng, tôi thực sự không yên tâm chút nào.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_08','V1022','王民警',8,'我全程在场调解，等房东到场后优先让你取出随身重要证件。','wǒ quán chéng zài chǎng tiáo jiě， děng fáng dōng dào chǎng hòu yōu xiān ràng nǐ qǔ chū suí shēn zhòng yào zhèng jiàn。','Tôi sẽ có mặt hòa giải từ đầu đến cuối, đợi chủ nhà đến sẽ ưu tiên cho anh/chị lấy giấy tờ quan trọng mang theo người trước.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1023','SKC1','校医院无法处理急症，拨打120同时同步告知国际学院辅导员',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1023','SIT1023','P1','suon_se','ban_chinh_thuc',NULL,'国内高校校医院仅处理轻症，重症统一转送综合医院，留学生可凭留学生医保报销部分急诊费用。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_01','V1023','阮明',1,'李导，我现在在校医院，医生说我的急症这里处理不了，已经拨打120送综合医院了。','lǐ dǎo， wǒ xiàn zài zài xiào yī yuàn， yī shēng shuō wǒ de jí zhèng zhè lǐ chǔ lǐ bù liǎo， yǐ jīng bō dǎ 120 sòng zōng hé yī yuàn le。','Cô Lý ơi, em đang ở phòng y tế trường, bác sĩ nói bệnh cấp của em ở đây không xử lý được, em đã gọi 120 để chuyển sang bệnh viện đa khoa rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_02','V1023','李辅导员',2,'是什么急症？救护车大概多久能到达校门口呢？','shì shén me jí zhèng？ jiù hù chē dà gài duō jiǔ néng dào dá xiào mén kǒu ne？','Là bệnh gì vậy? Xe cứu thương khoảng bao lâu nữa thì đến cổng trường?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_03','V1023','阮明',3,'急性肠胃炎伴随剧烈脱水，校医院缺少输液设备，救护车十分钟就到啦。','jí xìng cháng wèi yán bàn suí jù liè tuō shuǐ， xiào yī yuàn quē shǎo shū yè shè bèi， jiù hù chē shí fēn zhōng jiù dào la。','Viêm dạ dày ruột cấp kèm mất nước nặng, phòng y tế trường lại thiếu thiết bị truyền dịch, xe cứu thương mười phút nữa là tới rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_04','V1023','李辅导员',4,'我现在登记你的情况，等下会跟急诊医院说明你留学生身份。','wǒ xiàn zài dēng jì nǐ de qíng kuàng， děng xià huì gēn jí zhěn yī yuàn shuō míng nǐ liú xué shēng shēn fèn。','Cô ghi nhận tình hình của em ngay đây, lát nữa sẽ báo với bệnh viện cấp cứu về thân phận du học sinh của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_05','V1023','阮明',5,'我一个人等救护车，居留卡、学生证都随身带着，方便登记就诊。','wǒ yí gè rén děng jiù hù chē， jū liú kǎ、 xué shēng zhèng dōu suí shēn dài zhe， fāng biàn dēng jì jiù zhěn。','Em một mình chờ xe cứu thương, thẻ cư trú và thẻ sinh viên em mang theo người hết rồi, để tiện đăng ký khám.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_06','V1023','李辅导员',6,'我处理完手头工作就赶去医院，有任何不舒服随时给我打电话。','wǒ chǔ lǐ wán shǒu tóu gōng zuò jiù gǎn qù yī yuàn， yǒu rèn hé bù shū fú suí shí gěi wǒ dǎ diàn huà。','Cô xử lý xong việc đang làm là chạy đến bệnh viện ngay, có gì khó chịu thì gọi cho cô bất cứ lúc nào nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_07','V1023','阮明',7,'好，麻烦您了，就医缴费相关流程我不太清楚，到时候还要请教您。','hǎo， má fán nín le， jiù yī jiǎo fèi xiāng guān liú chéng wǒ bù tài qīng chǔ， dào shí hòu hái yào qǐng jiào nín。','Dạ vâng, phiền cô rồi ạ, quy trình khám chữa bệnh và đóng tiền em không rành lắm, lát nữa còn phải hỏi cô.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_08','V1023','李辅导员',8,'放心，留学生医保报销材料我之后会发给你，安心就医就好。','fàng xīn， liú xué shēng yī bǎo bào xiāo cái liào wǒ zhī hòu huì fā gěi nǐ， ān xīn jiù yī jiù hǎo。','Yên tâm đi, hồ sơ bảo hiểm y tế dành cho du học sinh để làm thủ tục hoàn tiền, cô sẽ gửi cho em sau, cứ yên tâm chữa bệnh trước đã.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1024','SKC1','异地就医刷卡银行卡被风控冻结，紧急致电银行客服解锁',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1024','SIT1024','P1','twist','chinh_thuc',NULL,'国内银行卡异地大额消费易触发风控冻结，线上临时解锁额度有限，大额资金解冻必须线下网点核验身份。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_01','V1024','阮明',1,'您好，我现在在外地医院缴费，银行卡刷卡提示账户被风控冻结，急需解锁。','nín hǎo， wǒ xiàn zài zài wài dì yī yuàn jiǎo fèi， yín háng kǎ shuā kǎ tí shì zhàng hù bèi fēng kòng dòng jié， jí xū jiě suǒ。','Xin chào, tôi hiện đang đóng viện phí ở bệnh viện tại một tỉnh khác, thẻ ngân hàng khi quẹt báo tài khoản bị kiểm soát rủi ro và đóng băng, tôi cần mở khóa gấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_02','V1024','客服',2,'请核实你的银行卡号、预留手机号、身份证/居留证件后四位。','qǐng hé shí nǐ de yín háng kǎ hào、 yù liú shǒu jī hào、 shēn fèn zhèng / jū liú zhèng jiàn hòu sì wèi。','Vui lòng cho tôi xác nhận số thẻ ngân hàng, số điện thoại đăng ký và bốn số cuối của chứng minh thư/thẻ cư trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_03','V1024','阮明',3,'卡号6217开头，预留手机号138XXXX2741，证件后四位3152，现在要付医药费啊。','kǎ hào 6217 kāi tóu， yù liú shǒu jī hào 138XXXX2741， zhèng jiàn hòu sì wèi 3152， xiàn zài yào fù yī yào fèi a。','Số thẻ bắt đầu bằng 6217, số điện thoại đăng ký là 138XXXX2741, bốn số cuối giấy tờ là 3152, tôi đang cần thanh toán tiền thuốc đây.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_04','V1024','客服',4,'系统检测到异地大额消费，自动触发风控保护，线上临时解锁有每日限额。','xì tǒng jiǎn cè dào yì dì dà é xiāo fèi， zì dòng chù fā fēng kòng bǎo hù， xiàn shàng lín shí jiě suǒ yǒu měi rì xiàn é。','Hệ thống phát hiện giao dịch số tiền lớn ở khu vực khác nên tự động kích hoạt bảo vệ rủi ro, việc mở khóa tạm thời trực tuyến có hạn mức mỗi ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_05','V1024','阮明',5,'医药费需要两千多元，临时限额只有一千，根本不够支付诊疗费用呢。','yī yào fèi xū yào liǎng qiān duō yuán， lín shí xiàn é zhǐ yǒu yī qiān， gēn běn bù gòu zhī fù zhěn liáo fèi yòng ne。','Tiền thuốc cần hơn hai nghìn tệ, mà hạn mức tạm thời chỉ có một nghìn, không đủ để thanh toán tiền khám chữa bệnh.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_06','V1024','客服',6,'线上解锁额度不足，需要你携带证件到线下网点办理全额解封。','xiàn shàng jiě suǒ é dù bù zú， xū yào nǐ xié dài zhèng jiàn dào xiàn xià wǎng diǎn bàn lǐ quán é jiě fēng。','Hạn mức mở khóa trực tuyến không đủ, anh/chị cần mang giấy tờ đến quầy giao dịch trực tiếp để mở khóa toàn bộ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_07','V1024','阮明',7,'我现在在医院没法出门，有没有别的办法临时提高支付额度？','wǒ xiàn zài zài yī yuàn méi fǎ chū mén， yǒu méi yǒu bié de bàn fǎ lín shí tí gāo zhī fù é dù？','Tôi đang ở bệnh viện không thể ra ngoài được, có cách nào khác để tạm thời nâng hạn mức thanh toán không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_08','V1024','客服',8,'实在抱歉，风控规则无法线上调整，建议你更换其他银行卡缴费。','shí zài bào qiàn， fēng kòng guī zé wú fǎ xiàn shàng diào zhěng， jiàn yì nǐ gēng huàn qí tā yín háng kǎ jiǎo fèi。','Thực sự xin lỗi, quy định kiểm soát rủi ro không thể điều chỉnh trực tuyến, đề nghị anh/chị dùng thẻ ngân hàng khác để thanh toán.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1025','SKC1','长途火车大面积晚点错过签证预约，向出入境窗口说明延误申请补受理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1025','SIT1025','P1','that_bai_nhe','chinh_thuc',NULL,'政务大厅预约号严格分时段管控，交通延误仅可优先预约次日时段，无法直接当日插队办理业务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_01','V1025','阮明',1,'吴主管您好，我原本今天预约办理签证续签，但是火车大面积晚点，错过了预约时段。','wú zhǔ guǎn nín hǎo， wǒ yuán běn jīn tiān yù yuē bàn lǐ qiān zhèng xù qiān， dàn shì huǒ chē dà miàn jī wǎn diǎn， cuò guò le yù yuē shí duàn。','Chào chị Ngô, tôi vốn định hôm nay đến làm thủ tục gia hạn visa theo lịch hẹn, nhưng tàu hỏa bị chậm trên diện rộng nên tôi lỡ mất khung giờ hẹn rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_02','V1025','吴主管',2,'先出示你的火车票晚点证明、预约回执，我先核实你的情况吧。','xiān chū shì nǐ de huǒ chē piào wǎn diǎn zhèng míng、 yù yuē huí zhí， wǒ xiān hé shí nǐ de qíng kuàng ba。','Anh/chị đưa giấy xác nhận tàu chậm và phiếu hẹn ra trước đã, để tôi kiểm tra tình hình của anh/chị.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_03','V1025','阮明',3,'铁路官方短信晚点通知我带来了，路上延误三个小时，赶到大厅已经过号了啊。','tiě lù guān fāng duǎn xìn wǎn diǎn tōng zhī wǒ dài lái le， lù shàng yán wù sān gè xiǎo shí， gǎn dào dà tīng yǐ jīng guò hào le a。','Tôi có mang theo tin nhắn thông báo tàu chậm chính thức của đường sắt đây, đường đi bị trễ mất ba tiếng, đến được sảnh thì đã quá số rồi ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_04','V1025','吴主管',4,'每日预约名额系统固定，当日过号无特殊事由不能现场插队办理。','měi rì yù yuē míng é xì tǒng gù dìng， dāng rì guò hào wú tè shū shì yóu bù néng xiàn chǎng chā duì bàn lǐ。','Số lượng hẹn mỗi ngày là do hệ thống cố định, nếu trong ngày quá số mà không có lý do đặc biệt thì không thể chen vào xử lý trực tiếp được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_05','V1025','阮明',5,'我下周就要出境参加交换项目，错过今天只能再等一周预约，时间来不及。','wǒ xià zhōu jiù yào chū jìng cān jiā jiāo huàn xiàng mù， cuò guò jīn tiān zhǐ néng zài děng yī zhōu yù yuē， shí jiān lái bù jí。','Tuần sau tôi phải xuất cảnh để tham gia chương trình trao đổi rồi, nếu lỡ hôm nay thì chỉ còn cách chờ thêm một tuần nữa mới hẹn được, thời gian không kịp mất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_06','V1025','吴主管',6,'火车晚点不属于法定加急事由，只能帮你优先预约明天最早时段号。','huǒ chē wǎn diǎn bù shǔ yú fǎ dìng jiā jí shì yóu， zhǐ néng bāng nǐ yōu xiān yù yuē míng tiān zuì zǎo shí duàn hào。','Tàu chậm không thuộc diện lý do khẩn cấp theo quy định, tôi chỉ có thể sắp xếp ưu tiên cho anh/chị lấy số sớm nhất vào ngày mai thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_07','V1025','阮明',7,'明天最早预约号是几点？我一定提前两小时到场，不会再迟到。','míng tiān zuì zǎo yù yuē hào shì jǐ diǎn？ wǒ yí dìng tí qián liǎng xiǎo shí dào chǎng， bú huì zài chí dào。','Số hẹn sớm nhất ngày mai là mấy giờ vậy ạ? Tôi chắc chắn sẽ đến sớm trước hai tiếng, sẽ không trễ nữa đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_08','V1025','吴主管',8,'早上八点第一号，我给你做优先标记，明天直接凭身份证取号。','zǎo shàng bā diǎn dì yī hào， wǒ gěi nǐ zuò yōu xiān biāo jì， míng tiān zhí jiē píng shēn fèn zhèng qǔ hào。','Số một lúc tám giờ sáng, tôi sẽ đánh dấu ưu tiên cho anh/chị, ngày mai cứ mang chứng minh thư đến lấy số trực tiếp là được.',NULL);
